checks.run:
for s in ssh apache2 php8.3-fpm hermes-supervisor; do systemctl is-active --quiet "$s" || { echo "inactive: $s"; exit 1; }; done
systemctl is-active --quiet borgmatic.timer || { echo "inactive: borgmatic.timer"; exit 1; }
if systemctl list-units --type=service --state=failed --no-legend 'wireguard-ops-cockpit-*' | grep -q .; then echo "failed wireguard-ops-cockpit service"; exit 1; fi

D=/var/tmp/cockpit-security-stageA
[ -s "$D/pre-upgrade-running-containers.txt" ] || { echo "no pre-upgrade container list"; exit 1; }
while read -r c; do docker ps --format '{{.Names}}' | grep -qxF "$c" || { echo "container not running: $c"; exit 1; }; done < "$D/pre-upgrade-running-containers.txt"
docker ps --format '{{.Names}}' | grep -qi hermes || { echo "hermes container not running"; exit 1; }
